import { createHash } from 'node:crypto';
import { gzipSync, gunzipSync } from 'node:zlib';

const historyMarker = '<!-- money-flow-ai-history:';
const maxCommentLength = 65_536;
const clock = new Intl.DateTimeFormat('ko-KR', {
  timeZone: 'Asia/Seoul',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
});
const terminal = new Set(['needs_human', 'failed', 'ci_failed', 'completed']);
const labels = {
  waiting_dependency: '선행 이슈 대기',
  developing: '개발 중',
  publishing: '게시 중',
  reviewing: '리뷰 중',
  waiting_ci: 'CI 대기',
  ci_failed: 'CI 실패',
  needs_human: '사람 확인 필요',
  failed: '실패',
  merged: '병합됨',
  completed: '완료',
};

export function progressHistory(body) {
  const line = body?.split('\n').at(-2);
  if (!line?.startsWith(historyMarker) || !line.endsWith(' -->')) return null;
  const compressed = Buffer.from(
    line.slice(historyMarker.length, -4),
    'base64',
  );
  const history = JSON.parse(gunzipSync(compressed).toString('utf8'));
  return Array.isArray(history) ? { runs: history } : history;
}

function compare(a, b) {
  return a.id - b.id || a.attempt - b.attempt;
}

export function appendProgress(history, execution, state, message, visible) {
  const { runs, archived } = history;
  if (archived && compare(execution, archived.through) <= 0) return null;
  let run = runs.find((item) => compare(item, execution) === 0);
  if (!run) {
    run = { ...execution, entries: [] };
    runs.push(run);
    runs.sort(compare);
  }
  const { status, code, head, pr, attempts, updatedAt } = state;
  const key = createHash('sha256')
    .update(JSON.stringify([status, code, head, pr, attempts, message]))
    .digest('base64url');
  if (run.entries.some((entry) => entry.key === key))
    return {
      duplicate: true,
      latest:
        runs.at(-1) === run &&
        run.current?.key === key &&
        !terminal.has(run.current.status),
    };
  const latest = runs.at(-1) === run && !terminal.has(run.current?.status);
  const entry = { key, status, code, message, visible, at: updatedAt, pr };
  run.entries.push(entry);
  if (latest) run.current = entry;
  return { latest };
}

export function importLegacyProgress(records) {
  const history = { runs: [] };
  for (const { state, body } of records) {
    const execution = { id: state.run ?? 0, attempt: 1 };
    const paragraphs = body.split('\n\n').slice(1);
    const end = paragraphs.findIndex((part) =>
      /^(?:\*\*진행 기록\*\*|<details>|Generated by Codex)/.test(part),
    );
    const message = paragraphs.slice(0, end < 0 ? 1 : end).join('\n\n');
    const event = appendProgress(history, execution, state, message, true);
    const run = history.runs.find((item) => compare(item, execution) === 0);
    const steps = paragraphs
      .slice(Math.max(0, end))
      .flatMap((paragraph) => paragraph.split('\n'))
      .filter((line) => /^- \d\d:\d\d /.test(line));
    if (steps.length && event && !event.duplicate) {
      run.legacy = [...new Set([...(run.legacy ?? []), ...steps])];
      run.entries.at(-1).visible = false;
    }
  }
  return history;
}

function statusLabel(status, code) {
  if (code === 'review_verification_needed') return '추가 검증 필요';
  return labels[status] ?? status;
}

export function renderProgress(history, state, repository, stateMarker) {
  const checkpoint = Buffer.from(JSON.stringify(state)).toString('base64');
  function render() {
    const { runs, archived } = history;
    const encoded = gzipSync(JSON.stringify(history)).toString('base64');
    const { current } = runs.at(-1);
    const pullUrl =
      current.pr && `https://github.com/${repository}/pull/${current.pr}`;
    const handoff =
      current.status === 'needs_human' &&
      pullUrl &&
      !current.message.includes(pullUrl)
        ? `[작업 PR #${current.pr}](${pullUrl})`
        : '';
    const actions = ({ id, attempt }) =>
      `https://github.com/${repository}/actions/runs/${id}/attempts/${attempt}`;
    const count = archived?.count ?? 0;
    const parts = runs.flatMap(({ id, attempt, entries, legacy }, index) => {
      const link = id ? ` · [Actions](${actions({ id, attempt })})` : '';
      const lines = entries
        .filter(({ visible }) => visible)
        .map(({ status, code, message, at, pr }) => {
          const time = at ? `${clock.format(new Date(at))} ` : '';
          const pull = pr
            ? ` · [PR #${pr}](https://github.com/${repository}/pull/${pr})`
            : '';
          return `- ${time}${statusLabel(status, code)} · ${message.replace(/\s*\n\s*/g, ' ')}${pull}`;
        });
      return [
        `**${count + index + 1}차 실행**${link}`,
        [...(legacy ?? []), ...lines].join('\n'),
      ];
    });
    return [
      `**AI 개발 · ${count + runs.length}차 실행 · ${statusLabel(current.status, current.code)}**`,
      current.message,
      handoff,
      '**진행 기록**',
      archived
        ? `댓글 길이 제한으로 이전 ${count}개 실행 기록을 줄였습니다. [이전 Actions 실행](${actions(archived.through)})`
        : '',
      ...parts,
      'Generated by Codex',
      `${historyMarker}${encoded} -->\n${stateMarker}${checkpoint} -->`,
    ]
      .filter(Boolean)
      .join('\n\n');
  }
  let text = render();
  while (text.length > maxCommentLength && history.runs.length > 1) {
    const { id, attempt } = history.runs.shift();
    history.archived = {
      count: (history.archived?.count ?? 0) + 1,
      through: { id, attempt },
    };
    text = render();
  }
  return text;
}
